INSERT INTO team_memberships (team_id, round_id, tournament_id, player_id, display_order)
SELECT seeded.team_id::uuid, seeded.round_id::uuid, seeded.tournament_id::uuid,
       seeded.player_id::uuid, seeded.display_order
FROM seeded
JOIN rounds seeded_round
  ON seeded_round.id = seeded.round_id::uuid
 AND seeded_round.tournament_id = seeded.tournament_id::uuid
 AND seeded_round.status = 'draft'
JOIN teams seeded_team
  ON seeded_team.id = seeded.team_id::uuid
 AND seeded_team.round_id = seeded.round_id::uuid
 AND seeded_team.tournament_id = seeded.tournament_id::uuid
WHERE NOT EXISTS (
    SELECT 1 FROM team_memberships existing
    WHERE existing.round_id = seeded.round_id::uuid
      AND existing.player_id = seeded.player_id::uuid
)
AND NOT EXISTS (
    SELECT 1 FROM team_memberships existing
    WHERE existing.team_id = seeded.team_id::uuid
      AND NOT EXISTS (
          SELECT 1 FROM seeded expected
          WHERE expected.team_id = seeded.team_id
            AND expected.player_id::uuid = existing.player_id
      )
)
ON CONFLICT DO NOTHING;

