  ON seeded_flight.id = seeded.flight_id::uuid
 AND seeded_flight.round_id = seeded.round_id::uuid
 AND seeded_flight.tournament_id = seeded.tournament_id::uuid
WHERE NOT EXISTS (
    SELECT 1 FROM flight_memberships existing
    WHERE existing.round_id = seeded.round_id::uuid
      AND existing.player_id = seeded.player_id::uuid
)
ON CONFLICT DO NOTHING;

WITH seeded_schedule(
    team_id, round_id, team_name, starting_hole, flight_id, flight_starting_hole
) AS (
    VALUES
    ('00000000-0000-0000-0000-000000005001'::uuid, '00000000-0000-0000-0000-000000004001'::uuid, 'Lag 1', 1, '00000000-0000-0000-0000-000000006001'::uuid, 1),
    ('00000000-0000-0000-0000-000000005002'::uuid, '00000000-0000-0000-0000-000000004001'::uuid, 'Lag 2', 1, '00000000-0000-0000-0000-000000006001'::uuid, 1),
    ('00000000-0000-0000-0000-000000005003'::uuid, '00000000-0000-0000-0000-000000004001'::uuid, 'Lag 3', 10, '00000000-0000-0000-0000-000000006002'::uuid, 10),
    ('00000000-0000-0000-0000-000000005004'::uuid, '00000000-0000-0000-0000-000000004001'::uuid, 'Lag 4', 10, '00000000-0000-0000-0000-000000006002'::uuid, 10),
    ('00000000-0000-0000-0000-000000005005'::uuid, '00000000-0000-0000-0000-000000004002'::uuid, 'Lag 1', 1, '00000000-0000-0000-0000-000000006003'::uuid, 1),
    ('00000000-0000-0000-0000-000000005006'::uuid, '00000000-0000-0000-0000-000000004002'::uuid, 'Lag 2', 1, '00000000-0000-0000-0000-000000006004'::uuid, 10),
    ('00000000-0000-0000-0000-000000005007'::uuid, '00000000-0000-0000-0000-000000004002'::uuid, 'Lag 3', 10, '00000000-0000-0000-0000-000000006003'::uuid, 1),
    ('00000000-0000-0000-0000-000000005008'::uuid, '00000000-0000-0000-0000-000000004002'::uuid, 'Lag 4', 10, '00000000-0000-0000-0000-000000006004'::uuid, 10)
)
UPDATE teams seeded_team
SET starting_hole = NULL
FROM seeded_schedule schedule
JOIN rounds seeded_round
  ON seeded_round.id = schedule.round_id
 AND seeded_round.status = 'draft'
JOIN flights seeded_flight
  ON seeded_flight.id = schedule.flight_id
 AND seeded_flight.round_id = schedule.round_id
 AND seeded_flight.tournament_id = '00000000-0000-0000-0000-000000002001'
 AND seeded_flight.starting_hole = schedule.flight_starting_hole
 AND seeded_flight.tee_time IS NULL
WHERE seeded_team.id = schedule.team_id
  AND seeded_team.round_id = schedule.round_id
  AND seeded_team.tournament_id = '00000000-0000-0000-0000-000000002001'
  AND seeded_team.name = schedule.team_name
  AND seeded_team.starting_hole = schedule.starting_hole
  AND seeded_team.tee_time IS NULL
  AND (SELECT count(*) FROM team_memberships tm
       WHERE tm.team_id = seeded_team.id) = 2
  AND NOT EXISTS (
      SELECT 1
      FROM team_memberships tm
      WHERE tm.team_id = seeded_team.id
        AND NOT EXISTS (
            SELECT 1 FROM flight_memberships fm
            WHERE fm.flight_id = seeded_flight.id
              AND fm.player_id = tm.player_id
        )
  )
  AND (SELECT count(*) FROM flight_memberships fm
       WHERE fm.flight_id = seeded_flight.id) = 4;

COMMIT;
